"""Recover bounds on the secret fair value t per item from the public leaderboard.

  pixi run python -m c2f.truth 2          # game 2 -> runs/truth_game_02.json + table

How: the leaderboard's /matchup cell for (X, Y) in a game is  net_X_vs_Y - net_Y_vs_X  (antisymmetric),
and /transactions tells us every charge a and whether it was accepted. Each pair's cell is a known
piecewise-constant function of the t's, so we keep, per item, only the t-intervals consistent with
every pair equation. Rejections are what carry information: a rejected fair charge contributes 2.5a,
a rejected fraud 0. Accepted charges contribute 2a either way (cap assumed not binding).

Two sources, combined: (1) the payout feed directly - a rejected charge still paid is fair (t >= a),
a rejected charge paid 0 whose size is known from an acceptance is fraud (t < a); (2) the matchup
equations above, which can narrow further but are dropped when inconsistent (e.g. the cap binds).

Output per item: t_lo (largest charge proven fair) and t_hi (smallest charge proven fraud, or inf).
"""

from __future__ import annotations

import collections
import itertools
import json
import sys

import requests

from c2f.feedback import B, teams, transactions
from c2f.submit import ROOT

TOL = 0.06


def _diff(a: float, acc: bool, t: float) -> float:
    """Contribution of one transaction to (issuer_net - reviewer_net) given t."""
    if a <= 0:
        return 0.0
    if a <= t + 1e-9:
        return 2 * a if acc else 2.5 * a
    return 2 * a if acc else 0.0


def payout_bounds(tx_list: list[dict]) -> dict[int, tuple[float, float | None]]:
    """Direct evidence from the payout feed, per item: (t_lo, t_hi or None).

    A rejected charge that was still paid (amount > 0) is proven fair: t >= amount. A rejected
    charge paid 0 whose size a is known from an acceptance is proven fraud: t < a.
    """
    acc: dict[tuple, float] = collections.defaultdict(float)
    rej: dict[tuple, list] = collections.defaultdict(list)
    for x in tx_list:
        key = (x["issuer"], x["line_item_index"])
        if x["accepted"]:
            acc[key] = max(acc[key], float(x["amount"]))
        else:
            rej[key].append(float(x["amount"]))
    items = sorted({x["line_item_index"] for x in tx_list})
    lo = {i: 0.0 for i in items}
    hi: dict[int, float | None] = {i: None for i in items}
    for (iss, i), amounts in rej.items():
        if max(amounts) > 0:
            lo[i] = max(lo[i], max(amounts))
        elif acc[(iss, i)] > 0:
            a = acc[(iss, i)]
            hi[i] = a if hi[i] is None else min(hi[i], a)
    return {i: (lo[i], hi[i]) for i in items}


def infer(game_id: int) -> dict[int, dict]:
    names = teams()
    tx: dict[tuple, dict] = {}
    for t in names:
        for x in transactions(game_id, t):
            tx[(x["issuer"], x["reviewer"], x["line_item_index"])] = x
    tx_list = list(tx.values())
    direct = payout_bounds(tx_list)
    games = [g["id"] for g in requests.get(f"{B}/games?completed_only=true&page_size=200", timeout=15).json()["items"]]
    gi = games.index(game_id)
    net = {}
    short = 0
    for t in names:
        for m in requests.get(f"{B}/matchup", params={"team": t}, timeout=15).json()["items"]:
            # A matchup row can lag the completed-games list: right after a game closes the
            # server may still serve cells without it (and a team that joined late is short
            # from the other end). The pair equations only ever NARROW the direct payout
            # bounds, so a missing cell costs precision, never correctness - skip it.
            cells = m.get("cells") or []
            if gi >= len(cells):
                short += 1
                continue
            net[(t, m["opponent"])] = cells[gi]
    if short:
        print(f"note: {short} matchup row(s) have no cell for game {game_id} yet - "
              f"using payout evidence only for those pairs (rerun `make truth G={game_id}` later to tighten)")

    items = sorted({x["line_item_index"] for x in tx_list})
    charges = {i: sorted({x["amount"] for x in tx_list if x["line_item_index"] == i and x["amount"] > 0}) for i in items}
    reps = {i: [0.0] + charges[i] for i in items}  # interval k: t in [reps[k], reps[k+1])
    feas = {i: set(range(len(reps[i]))) for i in items}
    for i in items:  # seed with the direct payout evidence; the pair equations can only narrow further
        d_lo, d_hi = direct[i]
        feas[i] = {k for k in feas[i] if reps[i][k] >= d_lo and (d_hi is None or reps[i][k] < d_hi)} or feas[i]
    by = collections.defaultdict(list)
    for x in tx_list:
        by[(x["issuer"], x["reviewer"])].append(x)

    def contrib(X: str, Y: str, i: int, k: int) -> float:
        t = reps[i][k]
        s = sum(_diff(x["amount"], x["accepted"], t) for x in by[(X, Y)] if x["line_item_index"] == i)
        s -= sum(_diff(x["amount"], x["accepted"], t) for x in by[(Y, X)] if x["line_item_index"] == i)
        return s

    eqs = []
    for (X, Y), v in net.items():
        if X >= Y:
            continue
        inv = [i for i in items if any(x["amount"] > 0 for x in by[(X, Y)] + by[(Y, X)] if x["line_item_index"] == i)]
        if inv:
            eqs.append((X, Y, v, inv))

    changed, rounds = True, 0
    while changed and rounds < 30:
        changed, rounds = False, rounds + 1
        for X, Y, v, inv in eqs:
            tabs = [{k: contrib(X, Y, i, k) for k in feas[i]} for i in inv]
            # exact, via subset-sum DP in cents over the distinct contribution values per item
            vals = [sorted({round(c * 100) for c in t.values()}) for t in tabs]
            n = len(inv)
            pre = [set() for _ in range(n + 1)]
            pre[0].add(0)
            for j in range(n):
                pre[j + 1] = {p + c for p in pre[j] for c in vals[j]}
            suf = [set() for _ in range(n + 1)]
            suf[n].add(0)
            for j in range(n - 1, -1, -1):
                suf[j] = {q + c for q in suf[j + 1] for c in vals[j]}
            target = round(v * 100)
            tol = int(TOL * 100) + 1
            ok = {i: set() for i in inv}
            for j, i in enumerate(inv):
                good_vals = set()
                for c in vals[j]:
                    rest = target - c
                    if any((rest - p - d) in suf[j + 1] for p in pre[j] for d in range(-tol, tol + 1)):
                        good_vals.add(c)
                for k, c in tabs[j].items():
                    if round(c * 100) in good_vals:
                        ok[i].add(k)
            if all(not ok[i] for i in inv):
                continue  # inconsistent (cap?) -> ignore this equation
            for i in inv:
                if ok[i] and ok[i] < feas[i]:
                    feas[i] = ok[i]
                    changed = True

    out = {}
    for i in items:
        ks = sorted(feas[i])
        lo = reps[i][ks[0]]
        hi = reps[i][ks[-1] + 1] if ks[-1] + 1 < len(reps[i]) else None
        out[i] = {"t_lo": lo, "t_hi": hi, "charges": charges[i]}
    return out


def main(game_id: int) -> None:
    res = infer(game_id)
    print(f"game {game_id}: fair-value bounds (t_lo = proven fair, t_hi = proven fraud)")
    for i, v in res.items():
        hi = "inf" if v["t_hi"] is None else f"{v['t_hi']:.0f}"
        print(f"  item {i:2d}: {v['t_lo']:7.2f} <= t < {hi:>5s}   charges seen: {[round(c) for c in v['charges']]}")
    p = ROOT / "runs" / f"truth_game_{game_id:02d}.json"
    p.write_text(json.dumps(res, indent=1))
    print(f"saved {p.relative_to(ROOT)}")


if __name__ == "__main__":
    gid = int(sys.argv[1])
    try:
        main(gid)
    except (requests.HTTPError, ValueError) as e:
        # 409 from /transactions or game missing from completed list: the game has not closed yet
        print(f"truth: game {gid} is not available on the leaderboard yet ({e.__class__.__name__}); rerun `make truth G={gid}` once it has closed")
        sys.exit(1)

"""After a game closes: what did everyone charge, who accepted what, how did we do.

  pixi run python -m c2f.feedback 2            # digest game 2
  C2F_TEAM="our name"  (optional; otherwise matched from runs/game_NN.json)

Per item it prints every team's charge a (their t estimate!), how many reviewers
accepted it, and the bounds on each team's acceptance limit b implied by their
accept/reject decisions. Market median of a across teams is a cheap second opinion on t.
"""

from __future__ import annotations

import collections
import functools
import json
import os
import sys
from statistics import median

import requests

from c2f.submit import ROOT

B = "https://c2f.public.quantco.cloud/leaderboard/api"
DEFAULT_TEAM = "AsianSuperNerds" 


FEED_CACHE = ROOT / "runs" / "feed"


@functools.lru_cache(maxsize=1)
def teams() -> list[str]:
    return [t["team_name"] for t in requests.get(f"{B}/matrix?page=1&game_limit=1", timeout=15).json()["items"]]


@functools.lru_cache(maxsize=1)
def completed() -> frozenset[int]:
    """Games the leaderboard reports as finished. Their feed can never change again."""
    try:
        r = requests.get(f"{B}/games", params={"completed_only": True, "page_size": 1000}, timeout=15)
        r.raise_for_status()
        return frozenset(int(g["id"]) for g in r.json()["items"])
    except Exception:  # noqa: BLE001 - no cache is a slowdown, not a failure
        return frozenset()


def transactions(game_id: int, team: str) -> list[dict]:
    """Transactions involving `team` in `game_id`, cached on disk once the game is closed.

    A closed game's feed is immutable, and the callers hammer it: `digest` pulls
    every team, and the tuner calls `digest` once per candidate per game. Without
    this, one `c2f.autotune` run was ~1,800 identical HTTP requests and took
    minutes; with it, everything after the first pass is local.
    """
    cacheable = game_id in completed()
    path = FEED_CACHE / f"g{game_id:02d}_{team.replace('/', '_')}.json"
    if cacheable and path.exists():
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            pass  # corrupt cache entry: fall through and refetch

    r = requests.get(f"{B}/transactions", params={"game_id": game_id, "team": team, "page_size": 1000}, timeout=15)
    r.raise_for_status()
    items = r.json()["items"]
    if cacheable:
        try:
            FEED_CACHE.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(items), encoding="utf-8")
        except OSError:
            pass  # cache is an optimisation; never fail the caller over it
    return items


def digest(game_id: int) -> dict:
    """amount in the feed is the PAYOUT: accepted -> min(a, c); rejected -> a if fair (a <= t) else 0."""
    names = teams()
    pay: dict[str, dict[int, list]] = collections.defaultdict(lambda: collections.defaultdict(list))  # issuer -> item -> [(reviewer, accepted, payout)]
    seen = set()
    for t in names:
        for x in transactions(game_id, t):
            key = (x["issuer"], x["reviewer"], x["line_item_index"])
            if key in seen:
                continue
            seen.add(key)
            pay[x["issuer"]][x["line_item_index"]].append((x["reviewer"], bool(x["accepted"]), float(x["amount"])))
    items = sorted({i for t in pay for i in pay[t]})
    issued: dict[str, dict[int, float | None]] = collections.defaultdict(dict)  # best guess of a
    fair: dict[str, dict[int, bool | None]] = collections.defaultdict(dict)    # a <= t ?
    t_lo: dict[int, float] = {i: 0.0 for i in items}
    t_hi: dict[int, float] = {i: float("inf") for i in items}
    for iss in names:
        for i in items:
            rows = pay[iss].get(i, [])
            acc_pay = [p for _, a, p in rows if a]
            rej_pay = [p for _, a, p in rows if not a]
            a_guess = max(acc_pay) if acc_pay else (max(rej_pay) if rej_pay and max(rej_pay) > 0 else None)
            issued[iss][i] = a_guess
            if rej_pay:
                if max(rej_pay) > 0:
                    fair[iss][i] = True
                    t_lo[i] = max(t_lo[i], max(rej_pay))
                elif a_guess and a_guess > 0:
                    fair[iss][i] = False
                    t_hi[i] = min(t_hi[i], a_guess)
                elif not acc_pay:
                    fair[iss][i] = None  # rejected everywhere with 0: fraud, but a unknown (>0) or a=0
            else:
                fair[iss][i] = None
    # reviewer limits: accepted a -> b >= a ; rejected a -> b < a
    b_lo: dict[str, dict[int, float]] = collections.defaultdict(dict)
    b_hi: dict[str, dict[int, float]] = collections.defaultdict(dict)
    for iss in names:
        for i in items:
            a = issued[iss][i]
            for rv, acc, _ in pay[iss].get(i, []):
                if a is None:
                    continue
                if acc:
                    b_lo[rv][i] = max(b_lo[rv].get(i, 0.0), a)
                elif a > 0:
                    b_hi[rv][i] = min(b_hi[rv].get(i, float("inf")), a)
    accepted = {iss: {i: [a for _, a, _ in pay[iss].get(i, [])] for i in items} for iss in names}
    return {"teams": names, "items": items, "issued": issued, "fair": fair, "t_lo": t_lo, "t_hi": t_hi,
            "accepted": accepted, "b_lo": b_lo, "b_hi": b_hi, "pay": pay}


def our_team(game_id: int, d: dict) -> str | None:
    if os.environ.get("C2F_TEAM"):
        return os.environ["C2F_TEAM"]
    return DEFAULT_TEAM
    p = ROOT / "runs" / f"game_{game_id:02d}.json"
    if not p.exists():
        return None
    rec = json.loads(p.read_text())
    subs = [s for s in rec.get("submissions", []) if isinstance(s.get("response"), list)]
    if not subs:
        return None
    ours_a = {r["index"]: r["charge_price"] for r in subs[-1]["rows"]}
    ours_b = {r["index"]: r["acceptance_limit"] for r in subs[-1]["rows"]}
    best, best_n = None, -1
    for t in d["teams"]:
        n = 0
        for i in ours_a:
            a = d["issued"][t].get(i)
            if a is not None and abs(a - ours_a[i]) < 0.01:
                n += 2
            lo, hi = d["b_lo"][t].get(i, 0.0), d["b_hi"][t].get(i, float("inf"))
            if lo <= ours_b[i] < hi:
                n += 1
        if n > best_n:
            best, best_n = t, n
    return best if best_n >= len(ours_a) else None


def main(game_id: int) -> None:
    d = digest(game_id)
    us = our_team(game_id, d)
    print(f"game {game_id}: {len(d['teams'])} teams, items {d['items']}   us = {us or '?'}")
    ours = None
    p = ROOT / "runs" / f"game_{game_id:02d}.json"
    if p.exists():
        rec = json.loads(p.read_text())
        subs = [s for s in rec.get("submissions", []) if isinstance(s.get("response"), list)]
        if subs:
            ours = {r["index"]: r for r in subs[-1]["rows"]}
    print(f"{'item':>4} {'t_lo':>7} {'t_hi':>7} {'mkt_med':>7} | {'our a':>7} {'our b':>7}  verdict")
    for i in d["items"]:
        charges = [a for t in d["teams"] for a in [d["issued"][t].get(i)] if a]
        med = median(charges) if charges else 0.0
        lo, hi = d["t_lo"][i], d["t_hi"][i]
        if ours and i in ours:
            a, b = ours[i]["charge_price"], ours[i]["acceptance_limit"]
            v = []
            if a > 0 and hi < float("inf") and a >= hi:
                v.append("a TOO HIGH (fraud)")
            if a > 0 and a <= lo and lo > 0:
                v.append("a fair")
            if b < lo:
                v.append("b TOO LOW (penalties)")
            if hi < float("inf") and b >= hi:
                v.append("b too high (paid fraud)")
            a_s, b_s, v_s = f"{a:7.1f}", f"{b:7.1f}", ", ".join(v) or "-"
        else:
            a_s = b_s = "      ?"
            v_s = "-"
        print(f"{i:>4} {lo:7.0f} {hi if hi < float('inf') else 0:7.0f} {med:7.0f} | {a_s} {b_s}  {v_s}")
    print("\n(t_hi 0 = unknown)  per item, charges by team (a, fair?, accepted):")
    for i in d["items"]:
        cells = []
        for t in d["teams"]:
            a = d["issued"][t].get(i)
            if a:
                f = d["fair"][t].get(i)
                acc = d["accepted"][t][i]
                cells.append(f"{t[:12]}={a:.0f}{'✓' if f else ('✗' if f is False else '?')}({sum(acc)}/{len(acc)})")
        print(f"  #{i}: " + "  ".join(cells))
    if us:
        perf = requests.get(f"{B}/performance", params={"team": us}, timeout=15).json()
        print("\nour performance so far:", json.dumps(perf))
    out = ROOT / "runs" / f"feedback_game_{game_id:02d}.json"
    slim = {k: v for k, v in d.items() if k != "pay"}
    out.write_text(json.dumps(slim, indent=1, default=str))
    print(f"saved {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main(int(sys.argv[1]))

